  2268   * read_config_read_memory():
  2269   *
  2270   * similar to read_config_read_data, but expects a generic memory
  2271   * pointer rather than a specific type of pointer.  Len is expected to
  2272   * be the amount of available memory.
  2273   */
  2274  char           *
  2275  read_config_read_memory(int type, char *readfrom,
  2276                          char *dataptr, size_t * len)
  2277  {
  2278      int            *intp;
  2279      unsigned int   *uintp;
  2280      char            buf[SPRINT_MAX_LEN];
  2281
  2282      if (!dataptr || !readfrom)
  2283          return NULL;
  2284
  2285      switch (type) {
  2286      case ASN_INTEGER:
  2287          if (*len < sizeof(int))
  2288              return NULL;
  2289          intp = (int *) dataptr;
  2290          readfrom = copy_nword(readfrom, buf, sizeof(buf));
  2291          *intp = atoi(buf);
  2292          *len = sizeof(int);
  2293          return readfrom;
  2294
  2295      case ASN_COUNTER:
  2296      case ASN_TIMETICKS:
  2297      case ASN_UNSIGNED:
  2298          if (*len < sizeof(unsigned int))
  2299              return NULL;
  2300          uintp = (unsigned int *) dataptr;
  2301          readfrom = copy_nword(readfrom, buf, sizeof(buf));
  2302          *uintp = strtoul(buf, NULL, 0);
  2303          *len = sizeof(unsigned int);
  2304          return readfrom;
  2305
  2306      case ASN_IPADDRESS:
  2307          if (*len < sizeof(int))
  2308              return NULL;
  2309          intp = (int *) dataptr;
  2310          readfrom = copy_nword(readfrom, buf, sizeof(buf));
  2311          *intp = inet_addr(buf);
  2312          if ((*intp == -1) && (strcmp(buf, "255.255.255.255") != 0))
  2313              return NULL;
  2314          *len = sizeof(int);
  2315          return readfrom;
  2316
  2317      case ASN_OCTET_STR:
  2318      case ASN_BIT_STR:
  2319      case ASN_PRIV_IMPLIED_OCTET_STR:
  2320          return read_config_read_octet_string(readfrom,
  2321                                               (u_char **) & dataptr, len);
  2322
  2323      case ASN_PRIV_IMPLIED_OBJECT_ID:
  2324      case ASN_OBJECT_ID:
  2325          readfrom =
  2326              read_config_read_objid(readfrom, (oid **) & dataptr, len);
  2327          *len *= sizeof(oid);
  2328          return readfrom;
  2329
  2330      case ASN_COUNTER64:
  2331          if (*len < sizeof(struct counter64))
  2332              return NULL;
  2333          *len = sizeof(struct counter64);
  2334          read64((struct counter64 *) dataptr, readfrom);
  2335          readfrom = skip_token(readfrom);
  2336          return readfrom;
  2337      }
