    61  void *af_get_null_terminated(const uint8_t **data, size_t *size) {
    62  #define STR_SIZE 75
    63    if (*size < STR_SIZE || (int)*size < 0) {
    64      return NULL;
    65    }
    66
    67    void *new_s = malloc(STR_SIZE + 1);
    68    memcpy(new_s, *data, STR_SIZE);
    69    ((uint8_t *)new_s)[STR_SIZE] = '\0';
    70
    71    *data = *data+STR_SIZE;
    72    *size -= STR_SIZE;
    73    return new_s;
    74  }
    75
    76  void *af_gb_get_random_data(const uint8_t **data, size_t *size, size_t to_get) {
    77    if (*size < to_get || (int)*size < 0) {
    78      return NULL;
    79    }
    80
    81    void *new_s = malloc(to_get);
    82    memcpy(new_s, *data, to_get);
    83
    84    pointer_arr[pointer_idx++] = new_s;
    85
    86    *data = *data + to_get;
    87    *size -= to_get;
    88
    89    return new_s;
    90  }
